arguments.file_text:
@using sv_767f06ebdae8403f8b5fd48a82188c36.Services

<div class="message-input-area">
    <textarea class="message-textarea"
              placeholder="@Placeholder"
              @bind="_text"
              @onkeydown="HandleKeyDown"
              rows="1" />
    <button class="send-btn" disabled="@string.IsNullOrWhiteSpace(_text)" @onclick="Send">
        @ButtonLabel
    </button>
</div>

@code {
    [Parameter] public string Placeholder { get; set; } = "Type a message…";
    [Parameter] public string ButtonLabel { get; set; } = "Send";
    [Parameter] public EventCallback<string> OnSend { get; set; }

    private string _text = string.Empty;

    private async Task HandleKeyDown(KeyboardEventArgs e)
    {
        if (e is { Key: "Enter", ShiftKey: false })
        {
            await Send();
        }
    }

    private async Task Send()
    {
        var content = _text.Trim();
        if (string.IsNullOrEmpty(content)) return;
        _text = string.Empty;
        await OnSend.InvokeAsync(content);
    }
}

.message-input-area {
    display: flex;
    gap: 8px;
    padding: 12px 16px;
    border-top: 1px solid rgba(255, 255, 255, 0.06);
    background: #2b2d31;
    align-items: flex-end;
}

.message-textarea {
    flex: 1;
    padding: 10px 14px;
    border: 1px solid rgba(255, 255, 255, 0.1);
    border-radius: 8px;
    background: #383a40;
    color: #dcddde;
    font-size: 0.93rem;
    font-family: inherit;
    resize: none;
    outline: none;
    min-height: 40px;
    max-height: 120px;
    line-height: 1.4;
}

.message-textarea::placeholder {
    color: #72767d;
}

.message-textarea:focus {
    border-color: #5865f2;
}

.send-btn {
    padding: 10px 20px;
    border: none;
    border-radius: 8px;
    background: #5865f2;
    color: #fff;
    font-weight: 600;
    font-size: 0.9rem;
    cursor: pointer;
    font-family: inherit;
    transition: background-color 0.15s;
    white-space: nowrap;
}

.send-btn:hover:not(:disabled) {
    background: #4752c4;
}

.send-btn:disabled {
    opacity: 0.5;
    cursor: not-allowed;
}

@using sv_767f06ebdae8403f8b5fd48a82188c36.Services
@inject IJSRuntime JS

<div class="message-list" @ref="_scrollContainer">
    @if (_loadingMore)
    {
        <div class="load-more-indicator">Loading older messages…</div>
    }
    else if (HasMore)
    {
        <button class="load-more-btn" @onclick="OnLoadMore">Load older messages</button>
    }

    @foreach (var message in Messages)
    {
        <MessageBubble Message="message"
                       ReplyCount="GetReplyCount(message.Id)"
                       OnOpenThread="OnOpenThread"
                       OnReact="OnReact" />
    }
</div>

@code {
    [Parameter, EditorRequired] public List<Message> Messages { get; set; } = [];
    [Parameter] public Dictionary<int, int> ThreadReplyCounts { get; set; } = [];
    [Parameter] public bool HasMore { get; set; }
    [Parameter] public EventCallback OnLoadMore { get; set; }
    [Parameter] public EventCallback<int> OnOpenThread { get; set; }
    [Parameter] public EventCallback<(int MessageId, string Emoji)> OnReact { get; set; }

    private ElementReference _scrollContainer;
    private bool _loadingMore;

    private int GetReplyCount(int messageId) =>
        ThreadReplyCounts.GetValueOrDefault(messageId);

    protected override async Task OnAfterRenderAsync(bool firstRender)
    {
        if (firstRender)
        {
            await ScrollToBottom();
        }
    }

    private async Task ScrollToBottom()
    {
        try
        {
            await JS.InvokeVoidAsync("eval",
                "document.querySelector('[b-message-list]')?.scrollTo(0, 999999) ?? " +
                "arguments[0]?.scrollTo(0, arguments[0].scrollHeight)",
                _scrollContainer);
        }
        catch
        {
            // Scroll is best-effort
        }
    }
}

.message-list {
    flex: 1;
    overflow-y: auto;
    padding: 8px 0;
    display: flex;
    flex-direction: column;
    gap: 2px;
}

.load-more-btn {
    align-self: center;
    margin: 8px 0;
    padding: 6px 16px;
    border: 1px solid rgba(255, 255, 255, 0.1);
    border-radius: 16px;
    background: transparent;
    color: #5865f2;
    font-size: 0.82rem;
    font-weight: 600;
    cursor: pointer;
    font-family: inherit;
}

.load-more-btn:hover {
    background: rgba(88, 101, 242, 0.1);
}

.load-more-indicator {
    text-align: center;
    padding: 10px;
    color: #888;
    font-size: 0.85rem;
}

