@using sv_767f06ebdae8403f8b5fd48a82188c36.Services

<div class="message-area">
    <div class="area-header">
        <h2 class="area-channel-name"># @Channel.Name</h2>
        <span class="area-channel-desc">@Channel.Description</span>
    </div>

    <MessageList Messages="Messages"
                 ThreadReplyCounts="ThreadReplyCounts"
                 HasMore="HasMore"
                 OnLoadMore="OnLoadMore"
                 OnOpenThread="OnOpenThread"
                 OnReact="OnReact" />

    <MessageInput Placeholder="@($"Message #{Channel.Name}")"
                  OnSend="OnSendMessage" />
</div>

@code {
    [Parameter, EditorRequired] public Channel Channel { get; set; } = default!;
    [Parameter, EditorRequired] public List<Message> Messages { get; set; } = [];
    [Parameter] public Dictionary<int, int> ThreadReplyCounts { get; set; } = [];
    [Parameter] public bool HasMore { get; set; }
    [Parameter] public EventCallback OnLoadMore { get; set; }
    [Parameter] public EventCallback<string> OnSendMessage { get; set; }
    [Parameter] public EventCallback<int> OnOpenThread { get; set; }
    [Parameter] public EventCallback<(int MessageId, string Emoji)> OnReact { get; set; }
}

.message-area {
    display: flex;
    flex-direction: column;
    height: 100%;
    background: #313338;
    overflow: hidden;
}

.area-header {
    padding: 12px 16px;
    border-bottom: 1px solid rgba(255, 255, 255, 0.06);
    display: flex;
    align-items: baseline;
    gap: 12px;
    flex-shrink: 0;
}

.area-channel-name {
    margin: 0;
    font-size: 1.1rem;
    font-weight: 700;
    color: #f2f3f5;
    white-space: nowrap;
}

.area-channel-desc {
    font-size: 0.85rem;
    color: #888;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
}

@using sv_767f06ebdae8403f8b5fd48a82188c36.Services

<div class="thread-panel">
    <div class="thread-header">
        <h3>Thread</h3>
        <button class="thread-close-btn" @onclick="OnClose" title="Close thread">✕</button>
    </div>

    @if (RootMessage is not null)
    {
        <div class="thread-root-quote">
            <span class="thread-root-author">@RootMessage.Author</span>
            <p class="thread-root-content">@RootMessage.Content</p>
        </div>

        <div class="thread-divider">
            <span>@ThreadMessages.Count @(ThreadMessages.Count == 1 ? "reply" : "replies")</span>
        </div>

        <div class="thread-replies">
            @foreach (var reply in ThreadMessages)
            {
                <div class="thread-reply">
                    <div class="thread-reply-header">
                        <span class="thread-reply-author">@reply.Author</span>
                        <span class="thread-reply-time">@FormatRelativeTime(reply.SentAt)</span>
                    </div>
                    <div class="thread-reply-content">@reply.Content</div>
                </div>
            }
        </div>

        <MessageInput Placeholder="Reply in thread…"
                      ButtonLabel="Reply"
                      OnSend="OnReply" />
    }
</div>

@code {
    [Parameter] public Message? RootMessage { get; set; }
    [Parameter] public List<Message> ThreadMessages { get; set; } = [];
    [Parameter] public EventCallback OnClose { get; set; }
    [Parameter] public EventCallback<string> OnReply { get; set; }

    private static string FormatRelativeTime(DateTime sentAt)
    {
        var diff = DateTime.UtcNow - sentAt;
        if (diff.TotalMinutes < 1) return "just now";
        if (diff.TotalMinutes < 60) return $"{(int)diff.TotalMinutes} min ago";
        if (diff.TotalHours < 24) return $"{(int)diff.TotalHours}h ago";
        if (diff.TotalDays < 7) return $"{(int)diff.TotalDays}d ago";
        return sentAt.ToString("MMM d, yyyy");
    }
}

.thread-panel {
    display: flex;
    flex-direction: column;
    height: 100%;
    background: #2b2d31;
    border-left: 1px solid rgba(255, 255, 255, 0.06);
    overflow: hidden;
}

.thread-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding: 12px 16px;
    border-bottom: 1px solid rgba(255, 255, 255, 0.06);
    flex-shrink: 0;
}

.thread-header h3 {
    margin: 0;
    font-size: 1rem;
    font-weight: 700;
    color: #f2f3f5;
}

.thread-close-btn {
    padding: 4px 8px;
    border: none;
    background: transparent;
    color: #b5bac1;
    font-size: 1.1rem;
    cursor: pointer;
    border-radius: 4px;
    line-height: 1;
}

.thread-close-btn:hover {
    background: rgba(255, 255, 255, 0.08);
    color: #fff;
}

.thread-root-quote {
    padding: 12px 16px;
    border-bottom: 1px solid rgba(255, 255, 255, 0.04);
    background: rgba(0, 0, 0, 0.15);
}

.thread-root-author {
    font-weight: 700;
    font-size: 0.9rem;
    color: #f2f3f5;
}

.thread-root-content {
    margin: 4px 0 0;
