@page "/chat"
@using sv_767f06ebdae8403f8b5fd48a82188c36.Services
@inject IChatService ChatService
@rendermode InteractiveServer

<PageTitle>Chat</PageTitle>

<div class="chat-layout">
    <div class="chat-sidebar">
        <ChannelSidebar Channels="_channels"
                        SelectedChannelId="_selectedChannelId"
                        OnChannelSelected="SelectChannelAsync" />
    </div>

    <div class="chat-main @(_threadOpen ? "" : "chat-main-wide")">
        @if (_selectedChannel is not null)
        {
            <MessageArea Channel="_selectedChannel"
                         Messages="_messages"
                         ThreadReplyCounts="_threadReplyCounts"
                         HasMore="_hasMoreMessages"
                         OnLoadMore="LoadOlderMessagesAsync"
                         OnSendMessage="SendMessageAsync"
                         OnOpenThread="OpenThreadAsync"
                         OnReact="HandleReactAsync" />
        }
        else
        {
            <div class="chat-placeholder">
                <p>Select a channel to start chatting</p>
            </div>
        }
    </div>

    @if (_threadOpen)
    {
        <div class="chat-thread">
            <ThreadPanel RootMessage="_threadRootMessage"
                         ThreadMessages="_threadMessages"
                         OnClose="CloseThread"
                         OnReply="SendThreadReplyAsync" />
        </div>
    }
</div>

@code {
    private const int PageSize = 30;

    private List<Channel>? _channels;
    private int _selectedChannelId;
    private Channel? _selectedChannel;
    private List<Message> _messages = [];
    private Dictionary<int, int> _threadReplyCounts = [];
    private bool _hasMoreMessages;

    // Thread state
    private bool _threadOpen;
    private int _threadRootMessageId;
    private Message? _threadRootMessage;
    private List<Message> _threadMessages = [];

    protected override async Task OnInitializedAsync()
    {
        _channels = await ChatService.GetChannelsAsync();
        if (_channels.Count > 0)
        {
            await SelectChannelAsync(_channels[0].Id);
        }
    }

    private async Task SelectChannelAsync(int channelId)
    {
        _selectedChannelId = channelId;
        _selectedChannel = _channels?.FirstOrDefault(c => c.Id == channelId);
        _messages = [];
        _threadReplyCounts = [];
        _hasMoreMessages = false;

        if (_selectedChannel is null) return;

        var loaded = await ChatService.GetMessagesAsync(channelId, 0, PageSize);
        _messages = loaded;
        _hasMoreMessages = loaded.Count >= PageSize;

        BuildThreadReplyCounts();

        _ = ChatService.MarkChannelReadAsync(channelId);
    }

    private async Task LoadOlderMessagesAsync()
    {
        var older = await ChatService.GetMessagesAsync(_selectedChannelId, _messages.Count, PageSize);
        _messages.InsertRange(0, older);
        _hasMoreMessages = older.Count >= PageSize;
        BuildThreadReplyCounts();
    }

    private async Task SendMessageAsync(string content)
    {
        var message = await ChatService.SendMessageAsync(_selectedChannelId, content, null);
        _messages.Add(message);
    }

    private async Task OpenThreadAsync(int rootMessageId)
    {
        _threadRootMessageId = rootMessageId;
        _threadRootMessage = _messages.FirstOrDefault(m => m.Id == rootMessageId);
        _threadMessages = await ChatService.GetThreadAsync(rootMessageId);
        _threadOpen = true;
    }

    private void CloseThread()
    {
        _threadOpen = false;
        _threadRootMessage = null;
        _threadMessages = [];
    }

    private async Task SendThreadReplyAsync(string content)
    {
        var reply = await ChatService.SendMessageAsync(_selectedChannelId, content, _threadRootMessageId);
        _threadMessages.Add(reply);

        // Update reply count in main view
        _threadReplyCounts[_threadRootMessageId] = _threadMessages.Count;
    }

    private async Task HandleReactAsync((int MessageId, string Emoji) reaction)
    {
        await ChatService.AddReactionAsync(reaction.MessageId, reaction.Emoji);

        // Optimistically update the UI
        var msg = _messages.FirstOrDefault(m => m.Id == reaction.MessageId);
        if (msg is not null)
        {
            var existing = msg.Reactions.FirstOrDefault(r => r.Emoji == reaction.Emoji);
            if (existing is not null)
            {
                existing.Users.Add("You");
            }
            else
            {
                msg.Reactions.Add(new Reaction(reaction.Emoji, ["You"]));
            }
        }
    }

    private void BuildThreadReplyCounts()
    {
        // Count messages that are replies (have ReplyToId) grouped by root
        _threadReplyCounts = _messages
            .Where(m => m.ReplyToId.HasValue)
            .GroupBy(m => m.ReplyToId!.Value)
            .ToDictionary(g => g.Key, g => g.Count());
    }
}

.chat-layout {
    display: flex;
    height: 100vh;
    overflow: hidden;
    background: #313338;
    color: #dcddde;
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
}

.chat-sidebar {
    width: 20%;
    min-width: 200px;
    max-width: 280px;
    flex-shrink: 0;
}

.chat-main {
    flex: 1;
    min-width: 0;
    display: flex;
    flex-direction: column;
}

.chat-main-wide {
    /* When no thread is open, takes remaining space */
}

.chat-thread {
    width: 25%;
    min-width: 260px;
    max-width: 380px;
    flex-shrink: 0;
}

.chat-placeholder {
    flex: 1;
    display: flex;
    align-items: center;
    justify-content: center;
}

.chat-placeholder p {
    color: #72767d;
    font-size: 1.1rem;
}

